-- Réplica mínima (colunas/constraints conferidas por leitura de estrutura) para banco DESCARTÁVEL.
CREATE ROLE anon; CREATE ROLE authenticated; CREATE ROLE service_role;
CREATE SCHEMA auth; CREATE TABLE auth.users (id uuid PRIMARY KEY);
CREATE TABLE public.team_time_employees (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), external_id text NOT NULL UNIQUE, matricula text, nome text NOT NULL, cargo text, departamento text, horario_previsto text, ativo boolean NOT NULL DEFAULT true, synced_at timestamptz NOT NULL DEFAULT now(), created_at timestamptz NOT NULL DEFAULT now(), oculto boolean NOT NULL DEFAULT false, oculto_por uuid, oculto_em timestamptz, user_id uuid UNIQUE REFERENCES auth.users(id) ON DELETE SET NULL, desligado_em date, horario_override text);
CREATE TABLE public.team_time_daily (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), employee_external_id text NOT NULL REFERENCES public.team_time_employees(external_id) ON DELETE CASCADE, dia date NOT NULL, horario_previsto text, primeira_marcacao text, ultima_marcacao text, marcacoes text[] NOT NULL DEFAULT '{}', horas_trabalhadas text, horas_extras text, situacao text NOT NULL DEFAULT 'aguardando' CHECK (situacao IN ('regular','atraso','sem_marcacao','incompleta','falta','hora_extra','inconsistencia','aguardando','em_andamento')), ocorrencia text, synced_at timestamptz NOT NULL DEFAULT now(), UNIQUE (employee_external_id, dia));
CREATE TABLE public.team_time_occurrences (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), external_key text NOT NULL UNIQUE, employee_external_id text NOT NULL REFERENCES public.team_time_employees(external_id) ON DELETE CASCADE, dia date NOT NULL, tipo text NOT NULL, descricao text, origem text NOT NULL DEFAULT 'ocorrencias', synced_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE public.team_time_sync_runs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), trigger text NOT NULL DEFAULT 'manual', status text NOT NULL DEFAULT 'running' CHECK (status IN ('running','success','error','not_configured')), started_at timestamptz NOT NULL DEFAULT now(), finished_at timestamptz, requested_by uuid, reference_date date, counts jsonb NOT NULL DEFAULT '{}', message text);
-- Tabelas que a importação nunca deve tocar (formato simplificado).
CREATE TABLE public.team_time_justifications (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), employee_external_id text NOT NULL, dia date NOT NULL, motivo text);
CREATE TABLE public.team_time_daily_overrides (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), employee_external_id text NOT NULL, dia date NOT NULL, valor text);
GRANT USAGE ON SCHEMA public TO anon, authenticated, service_role;
GRANT ALL ON ALL TABLES IN SCHEMA public TO service_role;
